export const oct8BlogSlugs=new Set(oct8BlogPosts.map(x=>x.slug));
export function getOct8BlogMetadata(slug:string):Metadata{const a=articles[slug as keyof typeof articles],canonical=`${site}/blog/${slug}`;return{title:a.title,description:a.excerpt,alternates:{canonical},openGraph:{title:a.title,description:a.excerpt,url:canonical,type:'article',publishedTime:published,images:[{url:image,alt:a.title}]}}}
export function renderOct8BlogArticle(slug:string){const a=articles[slug as keyof typeof articles],canonical=`${site}/blog/${slug}`,schema={'@context':'https://schema.org','@type':'Article',headline:a.title,description:a.excerpt,datePublished:published,dateModified:published,mainEntityOfPage:canonical,image:site+image,author:{'@type':'Organization',name:'Outsourced Labor',url:site},publisher:{'@type':'Organization',name:'Outsourced Labor',url:site},citation:a.sources.map(x=>x.url)};return <><Header/><main className="article-page"><JsonLd data={schema}/><article className="container article-shell"><header className="article-header"><p className="eyebrow">Philippines workforce operations guide</p><h1>{a.title}</h1><p className="lead">{a.excerpt}</p><div className="article-meta"><span>10 min read</span><time dateTime={published}>{visible}</time></div><img src={image} alt="Operations specialist reviewing a controlled work queue" width="1200" height="630"/></header><div className="article-body">{a.sections.map(section=><section key={section.heading}><h2>{section.heading}</h2>{section.paragraphs.map(p=><p key={p}>{p}</p>)}</section>)}<p>For a scoped next step, review <a href={`/services/${oct8Services[slug]}`}>{oct8Services[slug].replaceAll('-',' ')}</a> or <a href="/contact-us">contact Outsourced Labor</a>. Keep consequential approvals with the accountable client owner.</p></div><section className="source-list"><h2>Authoritative references</h2><ol>{a.sources.map(source=><li key={source.url}><a href={source.url} target="_blank" rel="noreferrer">{source.name}</a> — {source.publisher}; checked {source.checked}</li>)}</ol></section></article><CTA/></main><Footer/></>}
